def digest(data):
    return hashlib.sha256(data).hexdigest()


def apply_patch(source, destination):
    source = source.resolve(strict=True)
    destination = destination.resolve()
    if destination.exists() or destination.is_relative_to(source):
        raise ValueError("输出目录必须尚不存在，且不能位于原版游戏目录内。")
    if not (source / "MAIN.EXE").is_file() or not (source / "KOUKAI2.COM").is_file():
        raise ValueError("请选择包含 MAIN.EXE 和 KOUKAI2.COM 的 DOS 游戏目录。")

    patches = json.loads(zlib.decompress(base64.b85decode(PATCH_DATA)))
    changes = {}
    for name, (original_sha, simplified_sha, spans) in patches.items():
        data = (source / name).read_bytes()
        if digest(data) != original_sha:
            raise ValueError(f"{name} 与支持的繁体原版不符。")
        updated = bytearray(data)
        for offset, delta_hex in spans:
            delta = bytes.fromhex(delta_hex)
            updated[offset:offset + len(delta)] = bytes(
                byte ^ mask for byte, mask in zip(data[offset:offset + len(delta)], delta)
            )
        if digest(updated) != simplified_sha:
            raise ValueError(f"{name} 的补丁结果校验失败。")
        changes[name] = updated

    with tempfile.TemporaryDirectory(prefix=".sea2-zh-", dir=destination.parent) as temp:
        copy = Path(temp) / "game"
        shutil.copytree(source, copy, ignore=shutil.ignore_patterns(
            "KOUKAI2.DAT", "KOUKAI2.*.DAT", ".sea2-*.lock"
        ))
        for name, data in changes.items():
            (copy / name).write_bytes(data)
        destination.mkdir()
        try:
            os.replace(copy, destination)
        except OSError:
            destination.rmdir()
            raise
    return len(changes)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path, help="繁体原版 DOS 游戏目录")
    parser.add_argument("destination", type=Path, help="尚不存在的简体版输出目录")
    args = parser.parse_args()
    try:
        count = apply_patch(args.source, args.destination)
    except (OSError, ValueError) as error:
        parser.exit(1, f"安装失败。{error}\n")
    print(f"已安装 {count} 个简体补丁文件。输出目录为 {args.destination}")


if __name__ == "__main__":
    main()
